"""Final coverage and conservative resource accounting from retained records."""
from pathlib import Path
from datetime import datetime,timezone
import json,collections,csv
from scripts.final.analyze_next_round import load,csvwrite
R=Path(__file__).resolve().parents[2];O=R/'results/next_round'
def dump(p,x):p.write_text(json.dumps(x,indent=2,sort_keys=True)+'\n')
def main():
    active=load();allj=[json.loads(p.read_text()) for p in (O/'jobs').glob('*.json')];tasks=json.load(open(R/'configs/next_round/job_manifest.json'))['tasks'];gate=json.load(open(O/'mechanism_gate.json'));completed={j['task']['task_id']:j for j in active};coverage=[]
    for t in tasks:
        j=completed.get(t['task_id']);status=j['status'] if j else 'NOT_RUN_MECHANISM_NOT_SUPPORTED' if t['phase']=='C' and not gate['formal_capped_experiment_triggered'] else 'NOT_RUN'
        coverage.append({**t,'execution_status':status,'run_id':j.get('run_id') if j else None})
    csvwrite(O/'planned_execution_coverage.csv',coverage)
    costs={'all_retained_campaign_versions':sum(j.get('cpu_seconds',0) for j in allj)}
    for name,path in [('same_FW_legacy_IRLS_audit','irls_vs_pdhg.json'),('synthetic','synthetic/resource_usage.json'),('geometry_pilot','geometry_pilot_summary.json'),('corrected_robustness','robustness_resource_usage.json'),('heat_preparation','heat_primary_preparation_usage.json'),('tiny_global_reference','five_point_global_check.json')]:
        x=json.load(open(O/path));costs[name]=sum(r.get('cpu_seconds',0) for r in x) if isinstance(x,list) else x['cpu_seconds']
    now=datetime.now(timezone.utc)
    previous_path=O/'resource_ledger.json'
    if previous_path.exists():
        previous=json.loads(previous_path.read_text())
        if previous.get('metered_cpu_seconds_by_component')==costs and previous.get('all_campaign_versions')==len(allj):now=datetime.fromisoformat(previous['recorded_at_utc'])
    start=datetime(2026,11,9,12,41,43,tzinfo=timezone.utc);upper=2*(now-start).total_seconds()/3600
    ledger={'metered_cpu_seconds_by_component':costs,'metered_cpu_core_hours':sum(costs.values())/3600,'conservative_session_wall_envelope_core_hours':upper,'envelope_definition':'Two single-thread experiment workers for the entire interval since verified backup, including idle time. It covers unmetered original preparation and SC endpoints; does not claim precise attribution. Lightweight tooling outside scientific workers is not represented by per-fit CPU.','budget_cpu_core_hours':36,'budget_exceeded':upper>36,'maximum_experiment_workers':2,'blas_threads_per_worker':1,'largest_recorded_fit_peak_rss_bytes':max(j.get('peak_rss_bytes',0) for j in allj),'rss_target_bytes':8*1024**3,'memory_limit_note':'Per-fit peaks and spot checks, not a continuously enforced aggregate RSS cap. No observed overrun.','GPU_or_paid_compute':False,'recorded_at_utc':now.isoformat(),'all_campaign_versions':len(allj),'active_campaign_versions':len(active),'synthetic_instances':100}
    dump(O/'resource_ledger.json',ledger)
    counts=collections.Counter(r['execution_status'] for r in coverage);dump(O/'execution_status.json',{'task_counts':dict(counts),'by_phase':{phase:dict(collections.Counter(r['execution_status'] for r in coverage if r['phase']==phase)) for phase in sorted({r['phase'] for r in coverage})},'formal_four_benchmark_mean_ACC_gain_pp':None,'formal_four_benchmark_mean_NMI_gain_pp':None,'practical_target':'NOT_ESTABLISHED','candidate_searches':{'N1_real_grid':'NOT_RUN_NOT_PROMOTED_AFTER_SYNTHETIC_PILOT','N2_primary':'EXECUTED' if sum(t['phase']=='N2_primary' for t in tasks)==sum(j['task']['phase']=='N2_primary' for j in active) else 'INCOMPLETE','N2_sensitivity':'NOT_RUN_NOT_PROMOTED_AFTER_PRIMARY','adaptive_robustness':'NOT_RUN_NO_SELECTION_RULE','external_RCC_benchmark':'NOT_RUN_MATLAB_ENVIRONMENT_NOT_VALIDATED'}})
    lines=['# Negative and conditional findings','','The practical four-benchmark +2pp ACC/nondecreasing NMI target is **not established**. Formal averages are NA. No complete fair 15-configuration capped search is claimed.','','- The locked incorrect-fusion gate supports 0/4 datasets, below the required two. Real-data C is not triggered. This does not rule out incorrect fusion at other gamma values.','- Oracle correction helps at some large gamma values, but is label-assisted and is compared separately with same-gamma matched controls. It is not a usable unsupervised method.','- At gamma=1, small shrinkage gains do not become stable net benefit across datasets. USPS remains an optimization limitation at important gamma values.','- Historical USPS E8/Y0/greedy gamma=1000 ACC 79.918/NMI 85.609 remains a strong recorded point. Fresh seeded F/W differ or lack provable historical identity; their uncertified poor outputs cannot invalidate that point or prove an objective limitation.','- Synthetic capped fusion avoids bridge-edge damage but matches simpler static deletion and squared fidelity; SC already separates those examples. At anchor contamination it can remove useful correction.','- The five-point local capped solution depends strongly on initialization (objectives 3 versus 8). Only exhaustive tiny-state enumeration supplies a global reference.','- The N1 primary synthetic pilot changes MSE without ACC/NMI improvement. No real-data superiority is established.','- Projected heat improves graph stability in the geometry pilot; primary clustering outcomes and hard-dimension/W-only controls are in heat_primary_summary.csv. Stability is not label accuracy. Restricted exact-kernel approximation diagnostics do not imply full-graph kNN fidelity.','- Corrected image robustness uses four fixed conditions, full reruns and native domains. These are descriptive conditions, not independent perturbation replicates; USPS uncertainty remains.','- Native prclust is validated only on a tiny software sanity check; external RCC is source-inspected, not a benchmark comparison.','- Old missing F/W/G arrays, unavailable historical dataset identities remain explicit limitations.','','All retained failures, cold and warm solver versions, trials, costs and unexecuted planned cells are published.']
    (O/'negative_findings.md').write_text('\n'.join(lines)+'\n')
    append='\n## Measured final status\n\nThe main mechanism gate is **0/4**, so the formal real-data capped search is **NOT_RUN_MECHANISM_NOT_SUPPORTED**; the four-benchmark practical target is **not established (NA)**. Synthetic results show damage avoidance shared by simpler controls, not gain beyond SC. N1 has no demonstrated ACC/NMI gain; N2 primary ablations and corrected full-pipeline robustness are reported separately.\n\n[Planned/executed coverage](results/next_round/planned_execution_coverage.csv), [heat ablations](results/next_round/heat_primary_summary.csv), [synthetic results](results/next_round/synthetic/summary.json), [corrected robustness](results/next_round/corrected_robustness_summary.csv), [resource ledger](results/next_round/resource_ledger.json), [execution decisions](docs/next_round/execution_decisions.md), [publication status](docs/final/publication_status.json).\n'
    append += f"\nMeasured fit/audit CPU: {sum(costs.values())/3600:.3f} core-hours; conservative session envelope at completion: {upper:.2f} core-hours, against the 36-hour cap. Maximum two single-thread experiment workers; per-fit RSS and enforcement limits are in the ledger. No task is described as budget-exhausted merely because it was not promoted.\n"
    p=R/'README.md';s=p.read_text().split('\n## Measured final status')[0];p.write_text(s+append)
    dump(O/'irls_audit_stop_explanation.json',{'raw_failure_records_retained':True,'USPS_gamma1000':'CG failure, info=12000; no usable result or certificate','USPS_gamma1':'Interrupted by recorded 1800-second large-fit guard; incomplete result, not certified','identity':'Fresh same-F/W comparisons; no claim to recover baseline historical G','guard_record':'irls_timeout_guard.json'})
    print(json.dumps(ledger,indent=2))
if __name__=='__main__':main()
